//! Bounded fixed SQL material producers. These facts are not a shutdown/source capability.
//! Every cursor and payload field is checked in PostgreSQL before crossing the wire.

use futures_util::TryStreamExt;
use openbot_domain::vault::SecretBytes;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};
use std::time::Duration;
use tokio_postgres::{Client, GenericClient};
use zeroize::{Zeroize, Zeroizing};

use super::native;
use crate::backup::whole_pg_capture_stream::CaptureClockCheck;

#[derive(Clone, Copy, Deserialize, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct CaptureSqlLimits {
    pub max_rows: u64,
    pub max_row_bytes: u64,
    pub max_field_bytes: u64,
    pub max_pages: u64,
    pub page_rows: u64,
    pub max_catalog_objects: u64,
    pub max_query_tasks: u64,
    pub phase_ns: u64,
}

/// One operation's cumulative counters. A failed/cancelled query is never refunded.
pub struct CaptureSqlBudget {
    limits: CaptureSqlLimits,
    deadline_ns: u64,
    max_metadata_bytes: u64,
    rows: u64,
    pages: u64,
    catalog: u64,
    queries: u64,
    metadata: u64,
    sensitive: Option<std::sync::Arc<CaptureDecodeBudget>>,
}

// One cold-start class is shared by the original wire, normal/audit SQL and maintenance
// consumers. Clock binding never resets its cumulative charge.
#[doc(hidden)]
pub struct CaptureDecodeBudget {
    state: std::sync::Mutex<SensitiveDecodeBound>,
}
struct SensitiveDecodeBound {
    max_count: u64,
    max_one_bytes: u64,
    charged_count: u64,
    clock: Option<std::sync::Arc<dyn CaptureClockCheck>>,
    poisoned: bool,
}
impl CaptureDecodeBudget {
    pub fn checked(
        max_count: u64,
        max_one_bytes: u64,
    ) -> Result<std::sync::Arc<Self>, CaptureSqlFailure> {
        if max_count == 0 || max_one_bytes < 8 * 1024 {
            return Err(CaptureSqlFailure::Bounds);
        }
        max_count.checked_mul(max_one_bytes).ok_or(CaptureSqlFailure::Bounds)?;
        usize::try_from(max_one_bytes).map_err(|_| CaptureSqlFailure::Bounds)?;
        Ok(std::sync::Arc::new(Self {
            state: std::sync::Mutex::new(SensitiveDecodeBound {
                max_count,
                max_one_bytes,
                charged_count: 0,
                clock: None,
                poisoned: false,
            }),
        }))
    }

    pub fn bind_original_clock(
        &self,
        clock: std::sync::Arc<dyn CaptureClockCheck>,
    ) -> Result<(), CaptureSqlFailure> {
        let mut state = self.state.lock().map_err(|_| CaptureSqlFailure::Bounds)?;
        if state.poisoned || state.clock.is_some() {
            state.poisoned = true;
            return Err(CaptureSqlFailure::Bounds);
        }
        // Keep the actual clock resident even if its first effect observation fails.
        // A failed bind must never leave later wire reads in the cold-start branch.
        state.clock = Some(clock);
        let checked = state.clock.as_ref().ok_or(CaptureSqlFailure::Bounds)?
            .require_effect().map_err(|_| CaptureSqlFailure::Clock);
        if checked.is_err() {
            state.poisoned = true;
        }
        checked
    }

    pub fn reserve_allocations(
        &self,
        allocations: &[(u64, u64)],
    ) -> Result<(), CaptureSqlFailure> {
        let mut state = self.state.lock().map_err(|_| CaptureSqlFailure::Bounds)?;
        if state.poisoned {
            return Err(CaptureSqlFailure::Bounds);
        }
        let checked = (|| {
            if let Some(clock) = state.clock.as_ref() {
                clock.require_effect().map_err(|_| CaptureSqlFailure::Clock)?;
            }
            let mut copies = 0_u64;
            for &(count, one_bytes) in allocations {
                if one_bytes > state.max_one_bytes || (count != 0 && one_bytes == 0) {
                    return Err(CaptureSqlFailure::Bounds);
                }
                count.checked_mul(one_bytes).ok_or(CaptureSqlFailure::Bounds)?;
                copies = copies.checked_add(count).ok_or(CaptureSqlFailure::Bounds)?;
            }
            let next = state.charged_count.checked_add(copies)
                .filter(|next| *next <= state.max_count)
                .ok_or(CaptureSqlFailure::Bounds)?;
            if let Some(clock) = state.clock.as_ref() {
                clock.require_effect().map_err(|_| CaptureSqlFailure::Clock)?;
            }
            Ok(next)
        })();
        match checked {
            Ok(next) => {
                state.charged_count = next;
                Ok(())
            }
            Err(failure) => {
                state.poisoned = true;
                Err(failure)
            }
        }
    }

    // A crate-private charging action, not a charged-count getter or a second writer.
    // Immutable M is returned to the original socket adapter only after one full credit
    // has been admitted by the same reserve_allocations transaction.
    pub(crate) fn reserve_wire_credit(&self) -> Result<u64, CaptureSqlFailure> {
        let one = self.state.lock().map_err(|_| CaptureSqlFailure::Bounds)?.max_one_bytes;
        self.reserve_allocations(&[(1, one)])?;
        Ok(one)
    }

    fn require_original_clock_binding(&self) -> Result<(), CaptureSqlFailure> {
        let mut state = self.state.lock().map_err(|_| CaptureSqlFailure::Bounds)?;
        if state.poisoned {
            return Err(CaptureSqlFailure::Bounds);
        }
        let checked = match state.clock.as_ref() {
            Some(clock) => clock.require_effect().map_err(|_| CaptureSqlFailure::Clock),
            None => Err(CaptureSqlFailure::Bounds),
        };
        if checked.is_err() {
            state.poisoned = true;
        }
        checked
    }
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CaptureSqlFailure {
    Clock,
    Bounds,
    Database,
    RowInvalid,
    UnknownLayout,
    SourceMismatch,
    CommitUnknown,
    RollbackUnknown,
}

impl CaptureSqlBudget {
    pub fn new(
        limits: CaptureSqlLimits,
        max_metadata_bytes: u64,
        original_t0_ns: u64,
    ) -> Result<Self, CaptureSqlFailure> {
        let values = [
            limits.max_rows,
            limits.max_row_bytes,
            limits.max_field_bytes,
            limits.max_pages,
            limits.page_rows,
            limits.max_catalog_objects,
            limits.max_query_tasks,
            limits.phase_ns,
            max_metadata_bytes,
        ];
        if values.contains(&0)
            || limits.max_field_bytes > limits.max_row_bytes
            || limits.page_rows > limits.max_rows
        {
            return Err(CaptureSqlFailure::Bounds);
        }
        limits
            .page_rows
            .checked_add(1)
            .and_then(|n| i64::try_from(n).ok())
            .ok_or(CaptureSqlFailure::Bounds)?;
        usize::try_from(limits.max_row_bytes).map_err(|_| CaptureSqlFailure::Bounds)?;
        let deadline_ns = original_t0_ns
            .checked_add(limits.phase_ns)
            .ok_or(CaptureSqlFailure::Bounds)?;
        Ok(Self {
            limits,
            deadline_ns,
            max_metadata_bytes,
            rows: 0,
            pages: 0,
            catalog: 0,
            queries: 0,
            metadata: 0,
            sensitive: None,
        })
    }

    // Adopt the original cold-start counter; no new allowance or counter reset.
    pub fn bind_sensitive_decode_bound(
        &mut self,
        original: std::sync::Arc<CaptureDecodeBudget>,
    ) -> Result<(), CaptureSqlFailure> {
        if self.sensitive.is_some() {
            return Err(CaptureSqlFailure::Bounds);
        }
        original.require_original_clock_binding()?;
        self.sensitive = Some(original);
        Ok(())
    }
    fn reserve_sensitive_page(&mut self, rows: u64) -> Result<(), CaptureSqlFailure> {
        let bound = self.sensitive.as_ref().ok_or(CaptureSqlFailure::Bounds)?;
        let one = self
            .limits
            .max_row_bytes
            .checked_add(32 * std::mem::size_of::<Option<String>>() as u64)
            .ok_or(CaptureSqlFailure::Bounds)?;
        // Preserve the original six-slot SQL admission and the SQL01 8 KiB minimum.
        // Original wire credits use this same cold-start counter, never another profile.
        let copies = rows.checked_mul(6).ok_or(CaptureSqlFailure::Bounds)?;
        bound.reserve_allocations(&[(copies, one.max(8 * 1024))])
    }

    pub fn reserve_material_metadata(
        &mut self,
        bytes: u64,
        clock: &dyn CaptureClockCheck,
    ) -> Result<(), CaptureSqlFailure> {
        self.reserve_known(0, 0, bytes, clock)
    }

    pub(crate) fn remaining(
        &self,
        clock: &dyn CaptureClockCheck,
    ) -> Result<Duration, CaptureSqlFailure> {
        clock
            .require_effect()
            .map_err(|_| CaptureSqlFailure::Clock)?;
        let now = clock.observed_ns().map_err(|_| CaptureSqlFailure::Clock)?;
        let sql = self
            .deadline_ns
            .checked_sub(now)
            .filter(|n| *n > 0)
            .ok_or(CaptureSqlFailure::Clock)?;
        let effect = clock
            .effect_remaining_ns()
            .map_err(|_| CaptureSqlFailure::Clock)?;
        Ok(Duration::from_nanos(sql.min(effect)))
    }

    pub(crate) fn reserve_query(
        &mut self,
        clock: &dyn CaptureClockCheck,
    ) -> Result<Duration, CaptureSqlFailure> {
        let remaining = self.remaining(clock)?;
        self.queries = self
            .queries
            .checked_add(1)
            .ok_or(CaptureSqlFailure::Bounds)?;
        if self.queries > self.limits.max_query_tasks {
            return Err(CaptureSqlFailure::Bounds);
        }
        Ok(remaining)
    }

    pub(crate) fn reserve_known(
        &mut self,
        queries: u64,
        rows: u64,
        bytes: u64,
        clock: &dyn CaptureClockCheck,
    ) -> Result<(), CaptureSqlFailure> {
        self.remaining(clock)?;
        let q = self
            .queries
            .checked_add(queries)
            .ok_or(CaptureSqlFailure::Bounds)?;
        let r = self
            .rows
            .checked_add(rows)
            .ok_or(CaptureSqlFailure::Bounds)?;
        let m = self
            .metadata
            .checked_add(bytes)
            .ok_or(CaptureSqlFailure::Bounds)?;
        if q > self.limits.max_query_tasks
            || r > self.limits.max_rows
            || m > self.max_metadata_bytes
        {
            return Err(CaptureSqlFailure::Bounds);
        }
        self.queries = q;
        self.rows = r;
        self.metadata = m;
        Ok(())
    }

    fn row(&mut self, bytes: u64, catalog: bool) -> Result<(), CaptureSqlFailure> {
        self.rows = self.rows.checked_add(1).ok_or(CaptureSqlFailure::Bounds)?;
        self.metadata = self
            .metadata
            .checked_add(bytes)
            .ok_or(CaptureSqlFailure::Bounds)?;
        if catalog {
            self.catalog = self
                .catalog
                .checked_add(1)
                .ok_or(CaptureSqlFailure::Bounds)?;
        }
        if self.rows > self.limits.max_rows
            || bytes > self.limits.max_row_bytes
            || self.metadata > self.max_metadata_bytes
            || self.catalog > self.limits.max_catalog_objects
        {
            return Err(CaptureSqlFailure::Bounds);
        }
        Ok(())
    }
}

/// Exact identity from the original installed authority/attested PG/Store. It is data to
/// compare; constructing it does not grant any PG, source, restore or filesystem authority.
pub struct CaptureDbExpectation {
    pub deployment_id: String,
    pub tenant_id: String,
    pub dataset_id: String,
    pub instance_id: String,
    pub system_identifier: String,
    pub database_oid: u32,
    pub store_id: String,
    pub root_device: String,
    pub root_inode: String,
    pub root_uid: String,
}

pub(crate) struct CapturedDbRow {
    pub projection: &'static str,
    pub fields: Vec<Option<String>>,
}
impl Drop for CapturedDbRow {
    fn drop(&mut self) {
        for text in self.fields.iter_mut().flatten() {
            text.zeroize();
        }
    }
}

struct SensitiveCapturedRow {
    projection: &'static str,
    encoded: SecretBytes,
}
pub struct CapturedDbFacts {
    rows: Vec<CapturedDbRow>,
    sensitive: Vec<SensitiveCapturedRow>,
    schema_sha256: [u8; 32],
    migrations_sha256: [u8; 32],
    frontier_sha256: [u8; 32],
    system_identifier: String,
    database_oid: u32,
}
impl CapturedDbFacts {
    pub fn schema_sha256(&self) -> [u8; 32] {
        self.schema_sha256
    }
    pub fn migrations_sha256(&self) -> [u8; 32] {
        self.migrations_sha256
    }
    pub fn frontier_sha256(&self) -> [u8; 32] {
        self.frontier_sha256
    }
    pub fn system_identifier(&self) -> &str {
        &self.system_identifier
    }
    pub fn database_oid(&self) -> u32 {
        self.database_oid
    }
    pub fn row_count(&self) -> usize {
        self.rows.len()
    }
    pub fn sensitive_reference_count(&self) -> usize {
        self.sensitive.len()
    }
    pub fn matches_after(&self, after: &Self) -> bool {
        self.schema_sha256 == after.schema_sha256
            && self.migrations_sha256 == after.migrations_sha256
            && self.frontier_sha256 == after.frontier_sha256
            && self.system_identifier == after.system_identifier
            && self.database_oid == after.database_oid
            && self.rows.len() == after.rows.len()
            && self
                .rows
                .iter()
                .zip(&after.rows)
                .all(|(a, b)| a.projection == b.projection && a.fields == b.fields)
            && self.sensitive.len() == after.sensitive.len()
            && self.sensitive.iter().zip(&after.sensitive).all(|(a, b)| {
                a.projection == b.projection && a.encoded.expose() == b.encoded.expose()
            })
    }
    // The original typed row is reconstructed only inside the already charged sensitive
    // decode bound registered by R474.
    pub fn capture_canary_row(
        &self,
    ) -> Result<crate::db::desktop_vault_canary::DesktopVaultCanaryRow, CaptureSqlFailure> {
        let mut rows = self
            .sensitive
            .iter()
            .filter(|row| row.projection == "canary");
        let row = rows.next().ok_or(CaptureSqlFailure::SourceMismatch)?;
        if rows.next().is_some() {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
        let mut fields: Vec<Option<String>> = serde_json::from_slice(row.encoded.expose())
            .map_err(|_| CaptureSqlFailure::RowInvalid)?;
        let result = (|| {
            let f = |index: usize| {
                fields
                    .get(index)
                    .and_then(Option::as_deref)
                    .ok_or(CaptureSqlFailure::RowInvalid)
            };
            if f(4)? != "1" || f(5)? != "1" {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            crate::db::desktop_vault_canary::DesktopVaultCanaryRow::new(
                f(0)?,
                f(1)?,
                f(2)?,
                f(3)?,
                f(6)?,
            )
            .map_err(|_| CaptureSqlFailure::RowInvalid)
        })();
        for s in fields.iter_mut().flatten() {
            s.zeroize();
        }
        result
    }
    /// Compare the complete same-Store snapshot with all six bounded registry projections.
    /// This is a consistency check only: Unknown/admitted rows are preserved, never refunded.
    pub fn verify_artifact_snapshot(
        &self,
        snapshot: &crate::artifact_store::capture::ArtifactSnapshot,
    ) -> Result<(), CaptureSqlFailure> {
        let mut physical = BTreeMap::new();
        for file in snapshot.files() {
            if file.relative_path == ".artifact-store-v1" {
                continue;
            }
            let (location, id) = file
                .relative_path
                .split_once('/')
                .ok_or(CaptureSqlFailure::UnknownLayout)?;
            if !matches!(location, "objects" | "staging")
                || uuid::Uuid::parse_str(id)
                    .ok()
                    .is_none_or(|value| value.to_string() != id)
                || physical.insert((location, id), file).is_some()
            {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        let mut operations = BTreeMap::new();
        let mut by_artifact = BTreeMap::new();
        let mut workspace_charge = BTreeMap::<(&str, &str), u64>::new();
        let mut run_identities = BTreeMap::<&str, u64>::new();
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_save_operations")
        {
            let id = field(row, 4)?;
            let artifact = field(row, 5)?;
            let state = field(row, 12)?;
            if operations.insert(id, row).is_some()
                || by_artifact.insert(artifact, row).is_some()
                || !matches!(
                    state,
                    "admitted"
                        | "io_started"
                        | "available"
                        | "failed_partial"
                        | "unresolved"
                        | "deleted"
                        | "expired"
                        | "missing"
                )
            {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            let n = run_identities.entry(field(row, 8)?).or_default();
            *n = n.checked_add(1).ok_or(CaptureSqlFailure::Bounds)?;
            let object = physical.get(&("objects", artifact));
            let staging = physical.get(&("staging", artifact));
            if matches!(state, "deleted" | "expired" | "missing") {
                if object.is_some()
                    || staging.is_some()
                    || row.fields[13..24].iter().any(Option::is_some)
                {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
                continue;
            }
            let namespace = (field(row, 14)?, field(row, 15)?);
            if !matches!(namespace.0, "thread" | "channel") {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            let charge = parse_unsigned(field(row, 18)?)?;
            let sum = workspace_charge.entry(namespace).or_default();
            *sum = sum.checked_add(charge).ok_or(CaptureSqlFailure::Bounds)?;
            let expected_bytes = parse_unsigned(field(row, 17)?)?;
            if charge > expected_bytes {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
            if matches!(state, "available" | "failed_partial") {
                if field(row, 19)? != "false" {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
                let location = field(row, 22)?;
                let actual = match location {
                    "object" => object,
                    "staging" => staging,
                    _ => return Err(CaptureSqlFailure::UnknownLayout),
                }
                .ok_or(CaptureSqlFailure::SourceMismatch)?;
                if object.is_some() && staging.is_some()
                    || actual.byte_length != parse_unsigned(field(row, 20)?)?
                    || hex(&actual.sha256) != field(row, 21)?
                    || charge != actual.byte_length
                {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
                if state == "available"
                    && (location != "object"
                        || field(row, 23)? != "installed"
                        || actual.byte_length != expected_bytes
                        || hex(&actual.sha256) != field(row, 16)?)
                {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
            } else if row.fields.get(19).and_then(Option::as_deref) == Some("true")
                && (object.is_some() || staging.is_some())
            {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        for (_, id) in physical.keys() {
            if !by_artifact.contains_key(id) {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        let mut records = BTreeMap::new();
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_records")
        {
            let operation = operations
                .get(field(row, 4)?)
                .ok_or(CaptureSqlFailure::SourceMismatch)?;
            if records.insert(field(row, 3)?, row).is_some() {
                return Err(CaptureSqlFailure::RowInvalid);
            }
            for (ri, oi) in [
                (3, 5),
                (4, 4),
                (5, 3),
                (6, 6),
                (7, 7),
                (8, 8),
                (9, 9),
                (10, 10),
                (11, 11),
                (12, 12),
            ] {
                if row.fields.get(ri) != operation.fields.get(oi) {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
            }
            match field(row, 12)? {
                "available" | "failed_partial" => {
                    for (ri, oi) in [(13, 14), (14, 15), (16, 20), (17, 21)] {
                        if row.fields.get(ri) != operation.fields.get(oi) {
                            return Err(CaptureSqlFailure::SourceMismatch);
                        }
                    }
                    if field(row, 18)? != "explicit_saved"
                        || field(row, 19)? != field(row, 6)?
                        || field(row, 15)? != "text/plain; charset=utf-8"
                    {
                        return Err(CaptureSqlFailure::SourceMismatch);
                    }
                }
                "deleted" | "expired" | "missing" => {
                    if row.fields[13..21].iter().any(Option::is_some) {
                        return Err(CaptureSqlFailure::SourceMismatch);
                    }
                }
                _ => return Err(CaptureSqlFailure::UnknownLayout),
            }
        }
        let mut receipts = BTreeSet::new();
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_saved_receipts")
        {
            let operation = operations
                .get(field(row, 3)?)
                .ok_or(CaptureSqlFailure::SourceMismatch)?;
            if !receipts.insert(field(row, 3)?) {
                return Err(CaptureSqlFailure::RowInvalid);
            }
            for (ri, oi) in [
                (3, 4),
                (4, 5),
                (5, 3),
                (6, 6),
                (7, 7),
                (8, 8),
                (9, 9),
                (10, 10),
                (11, 11),
            ] {
                if row.fields.get(ri) != operation.fields.get(oi) {
                    return Err(CaptureSqlFailure::SourceMismatch);
                }
            }
            if !matches!(
                field(operation, 12)?,
                "available" | "deleted" | "expired" | "missing"
            ) {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        for (id, operation) in &operations {
            if matches!(
                field(operation, 12)?,
                "available" | "failed_partial" | "deleted" | "expired" | "missing"
            ) && !records.contains_key(field(operation, 5)?)
            {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
            if field(operation, 12)? == "available" && !receipts.contains(id) {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_workspace_quotas")
        {
            let key = (field(row, 3)?, field(row, 4)?);
            let actual = parse_unsigned(field(row, 5)?)?;
            if workspace_charge.remove(&key).unwrap_or(0) != actual {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        if !workspace_charge.is_empty() {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_run_quotas")
        {
            if run_identities.remove(field(row, 3)?).unwrap_or(0) != parse_unsigned(field(row, 4)?)?
            {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
        if !run_identities.is_empty() {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
        let mut fences = BTreeSet::new();
        for row in self
            .rows
            .iter()
            .filter(|r| r.projection == "artifact_cleanup_fences")
        {
            let operation = operations
                .get(field(row, 3)?)
                .ok_or(CaptureSqlFailure::SourceMismatch)?;
            if !fences.insert(field(row, 4)?)
                || field(row, 4)? != field(operation, 5)?
                || field(row, 5)? != "deleted"
            {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
            match field(row, 6)? {
                "armed" if field(operation, 12)? == "available" => (),
                "completed" if field(operation, 12)? == "deleted" => (),
                _ => return Err(CaptureSqlFailure::SourceMismatch),
            }
        }
        Ok(())
    }
    /// Only public metadata rows are serialized. Secret/canary/envelope rows never enter this
    /// ordinary byte stream, and no arbitrary SQL or server diagnostic is returned.
    pub fn write_projection(
        &self,
        names: &[&str],
        output: &mut impl std::io::Write,
    ) -> Result<(), CaptureSqlFailure> {
        // Validate the entire fixed selection before writing even one public row.
        // A misspelled or sensitive name must not become an empty-success assertion.
        if names.is_empty() || names.len() > ALL_PROJECTIONS.len() {
            return Err(CaptureSqlFailure::UnknownLayout);
        }
        for (index, name) in names.iter().enumerate() {
            if names[..index].contains(name)
                || !ALL_PROJECTIONS.iter().any(|projection| {
                    projection.name == *name && !projection.sensitive
                })
            {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
        }
        for row in &self.rows {
            if names.contains(&row.projection) {
                serde_json::to_writer(&mut *output, &(row.projection, &row.fields))
                    .map_err(|_| CaptureSqlFailure::Database)?;
                output
                    .write_all(b"\n")
                    .map_err(|_| CaptureSqlFailure::Database)?;
            }
        }
        Ok(())
    }
}

struct Projection {
    name: &'static str,
    sql: &'static str,
    cursor: &'static [usize],
    catalog: bool,
    sensitive: bool,
}

async fn read_projection<C: GenericClient + Sync>(
    client: &C,
    projection: &Projection,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<Vec<CapturedDbRow>, CaptureSqlFailure> {
    let mut cursor: [Option<String>; 3] = [None, None, None];
    let mut output = Vec::new();
    loop {
        let duration = budget.reserve_query(clock)?;
        budget.pages = budget
            .pages
            .checked_add(1)
            .ok_or(CaptureSqlFailure::Bounds)?;
        if budget.pages > budget.limits.max_pages {
            return Err(CaptureSqlFailure::Bounds);
        }
        let page = budget.limits.page_rows.min(
            budget
                .limits
                .max_rows
                .checked_sub(budget.rows)
                .ok_or(CaptureSqlFailure::Bounds)?,
        );
        if page == 0 {
            return Err(CaptureSqlFailure::Bounds);
        }
        let limit = i64::try_from(page.checked_add(1).ok_or(CaptureSqlFailure::Bounds)?)
            .map_err(|_| CaptureSqlFailure::Bounds)?;
        let field =
            i64::try_from(budget.limits.max_field_bytes).map_err(|_| CaptureSqlFailure::Bounds)?;
        let row_limit =
            i64::try_from(budget.limits.max_row_bytes).map_err(|_| CaptureSqlFailure::Bounds)?;
        let params: [&(dyn tokio_postgres::types::ToSql + Sync); 9] = [
            &cursor[0],
            &cursor[1],
            &cursor[2],
            &field,
            &row_limit,
            &limit,
            &expected.deployment_id,
            &expected.tenant_id,
            &expected.dataset_id,
        ];
        if projection.sensitive {
            budget.reserve_sensitive_page(
                u64::try_from(limit).map_err(|_| CaptureSqlFailure::Bounds)?,
            )?;
        }
        let stream = tokio::time::timeout(duration, client.query_raw(projection.sql, params))
            .await
            .map_err(|_| CaptureSqlFailure::Database)?
            .map_err(|_| CaptureSqlFailure::Database)?;
        tokio::pin!(stream);
        let mut seen = 0_u64;
        let mut next = cursor.clone();
        loop {
            let duration = budget.remaining(clock)?;
            let row = tokio::time::timeout(duration, stream.try_next())
                .await
                .map_err(|_| CaptureSqlFailure::Database)?
                .map_err(|_| CaptureSqlFailure::Database)?;
            let Some(row) = row else {
                break;
            };
            // The oversize control row and the lookahead are actual rows, never refunded.
            let oversized: bool = row.try_get(0).map_err(|_| CaptureSqlFailure::RowInvalid)?;
            // Own the wire clone under wiping Drop before any fallible budget check.
            // The PostgreSQL driver's internal buffers are outside this owned allocation.
            let payload = row
                .try_get::<_, Option<String>>(1)
                .map_err(|_| CaptureSqlFailure::RowInvalid)?
                .map(Zeroizing::new);
            let bytes = payload.as_ref().map_or(16, |p| p.len() as u64);
            // Charge decoded strings, Vec slots, retained row and the temporary wire payload
            // before serde allocates them. The static projection has at most 32 fields.
            let memory = bytes
                .checked_mul(4)
                .and_then(|n| n.checked_add(32 * std::mem::size_of::<Option<String>>() as u64))
                .and_then(|n| n.checked_add(std::mem::size_of::<CapturedDbRow>() as u64))
                .ok_or(CaptureSqlFailure::Bounds)?;
            budget.row(bytes, projection.catalog)?;
            budget.metadata = budget
                .metadata
                .checked_add(memory)
                .ok_or(CaptureSqlFailure::Bounds)?;
            if budget.metadata > budget.max_metadata_bytes {
                return Err(CaptureSqlFailure::Bounds);
            }
            if oversized {
                return Err(CaptureSqlFailure::Bounds);
            }
            let payload = payload.as_ref().ok_or(CaptureSqlFailure::RowInvalid)?;
            // Establish the existing row's wiping custody immediately after a successful
            // decode, including field rejection and the unused lookahead row.
            let captured = CapturedDbRow {
                projection: projection.name,
                fields: serde_json::from_str::<Vec<Option<String>>>(payload)
                    .map_err(|_| CaptureSqlFailure::RowInvalid)?,
            };
            if captured
                .fields
                .iter()
                .flatten()
                .any(|s| s.len() as u64 > budget.limits.max_field_bytes)
            {
                return Err(CaptureSqlFailure::Bounds);
            }
            seen = seen.checked_add(1).ok_or(CaptureSqlFailure::Bounds)?;
            if seen <= page {
                for (slot, index) in projection.cursor.iter().enumerate() {
                    next[slot] = Some(
                        captured
                            .fields
                            .get(*index)
                            .and_then(Option::as_ref)
                            .ok_or(CaptureSqlFailure::RowInvalid)?
                            .clone(),
                    );
                }
                output.push(captured);
            }
        }
        budget.remaining(clock)?;
        if seen <= page {
            break;
        }
        if next == cursor || projection.cursor.is_empty() {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        cursor = next;
    }
    Ok(output)
}

pub(crate) async fn read_capture_audit<C: GenericClient + Sync>(
    client: &C,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<Vec<CapturedDbRow>, CaptureSqlFailure> {
    let neutral = CaptureDbExpectation {
        deployment_id: String::new(),
        tenant_id: String::new(),
        dataset_id: String::new(),
        instance_id: String::new(),
        system_identifier: String::new(),
        database_oid: 0,
        store_id: String::new(),
        root_device: String::new(),
        root_inode: String::new(),
        root_uid: String::new(),
    };
    let mut rows = read_projection(client, &AUDIT_EVENTS, &neutral, budget, clock).await?;
    rows.extend(read_projection(client, &AUDIT_CHECKPOINTS, &neutral, budget, clock).await?);
    Ok(rows)
}

/// Original bounded identity observation. This is comparison data, never a source permit.
pub struct CapturePgIdentity {
    system_identifier: String,
    database_oid: u32,
}
impl CapturePgIdentity {
    pub fn system_identifier(&self) -> &str {
        &self.system_identifier
    }
    pub fn database_oid(&self) -> u32 {
        self.database_oid
    }
}
pub(crate) async fn read_capture_identity(
    client: &Client,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<CapturePgIdentity, CaptureSqlFailure> {
    let neutral = CaptureDbExpectation {
        deployment_id: String::new(),
        tenant_id: String::new(),
        dataset_id: String::new(),
        instance_id: String::new(),
        system_identifier: String::new(),
        database_oid: 0,
        store_id: String::new(),
        root_device: String::new(),
        root_inode: String::new(),
        root_uid: String::new(),
    };
    let rows = read_projection(client, &PG_IDENTITY, &neutral, budget, clock).await?;
    if rows.len() != 1 {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    let system_identifier = field(&rows[0], 0)?.to_owned();
    let database_oid = field(&rows[0], 1)?
        .parse::<u32>()
        .map_err(|_| CaptureSqlFailure::RowInvalid)?;
    if system_identifier.is_empty()
        || !system_identifier.bytes().all(|b| b.is_ascii_digit())
        || database_oid == 0
    {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    Ok(CapturePgIdentity {
        system_identifier,
        database_oid,
    })
}

// The normal original-Pool read has additional pre-shutdown safety observations.
// Their rows are validated here, never added to common source equality/hash facts.
pub(crate) async fn collect_normal_database_materials_before(
    client: &Client,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<CapturedDbFacts, CaptureSqlFailure> {
    collect_database_materials_in_transaction(client, expected, budget, clock, true).await
}

pub async fn collect_database_materials_before(
    client: &Client,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<CapturedDbFacts, CaptureSqlFailure> {
    collect_database_materials_in_transaction(client, expected, budget, clock, false).await
}

async fn collect_database_materials_in_transaction(
    client: &Client,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
    normal_safety: bool,
) -> Result<CapturedDbFacts, CaptureSqlFailure> {
    let duration = budget.reserve_query(clock)?;
    tokio::time::timeout(duration,client.batch_execute("BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL timezone='UTC'"))
        .await.map_err(|_| CaptureSqlFailure::Database)?.map_err(|_| CaptureSqlFailure::Database)?;
    let collected = async {
        if normal_safety {
            verify_normal_capture_safety(client, expected, budget, clock).await?;
        }
        collect_in_snapshot(client, expected, budget, clock).await
    }
    .await;
    match collected {
        Ok(facts) => {
            let duration = budget.reserve_query(clock)?;
            tokio::time::timeout(duration, client.batch_execute("COMMIT"))
                .await
                .map_err(|_| CaptureSqlFailure::CommitUnknown)?
                .map_err(|_| CaptureSqlFailure::CommitUnknown)?;
            budget.remaining(clock)?;
            Ok(facts)
        }
        Err(error) => {
            // A rollback is closing work, not a new source query. The external owner retains
            // this original client/driver until its real result; failure never becomes closed.
            clock
                .require_closing()
                .map_err(|_| CaptureSqlFailure::RollbackUnknown)?;
            let ns = clock
                .closing_remaining_ns()
                .map_err(|_| CaptureSqlFailure::RollbackUnknown)?;
            tokio::time::timeout(Duration::from_nanos(ns), client.batch_execute("ROLLBACK"))
                .await
                .map_err(|_| CaptureSqlFailure::RollbackUnknown)?
                .map_err(|_| CaptureSqlFailure::RollbackUnknown)?;
            clock
                .require_closing()
                .map_err(|_| CaptureSqlFailure::RollbackUnknown)?;
            Err(error)
        }
    }
}

// Fixed boolean observations only: no GUC value, role setting, tablespace path or
// server diagnostic crosses the wire. Use the original row/page/query/metadata budget.
async fn verify_normal_capture_safety(
    client: &Client,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<(), CaptureSqlFailure> {
    let role = read_projection(client, &NORMAL_ROLE_SETTINGS, expected, budget, clock).await?;
    require_normal_boolean_gate(&role, 1)?;
    let spaces = read_projection(client, &NORMAL_TABLESPACES, expected, budget, clock).await?;
    if spaces.len() != 2 {
        return Err(CaptureSqlFailure::UnknownLayout);
    }
    let mut saw_default = false;
    let mut saw_global = false;
    for row in &spaces {
        if row.fields.len() != 3 {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        let default = normal_safety_bool(row, 0)?;
        let global = normal_safety_bool(row, 1)?;
        let local = normal_safety_bool(row, 2)?;
        if !local || default == global || (default && saw_default) || (global && saw_global) {
            return Err(CaptureSqlFailure::UnknownLayout);
        }
        saw_default |= default;
        saw_global |= global;
    }
    if !saw_default || !saw_global {
        return Err(CaptureSqlFailure::UnknownLayout);
    }
    let hooks = read_projection(client, &NORMAL_EXTERNAL_HOOKS, expected, budget, clock).await?;
    require_normal_boolean_gate(&hooks, 12)?;
    // The original source-owner structural FD lexer must precede this SQL.
    // These observations do not manufacture that proof or bound PG's internal work.
    let paths = read_projection(client, &NORMAL_CONFIG_PATHS, expected, budget, clock).await?;
    require_normal_boolean_gate(&paths, 3)?;
    let files = read_projection(client, &NORMAL_FILE_SETTINGS, expected, budget, clock).await?;
    verify_normal_file_settings(&files)
}

fn require_normal_boolean_gate(
    rows: &[CapturedDbRow],
    width: usize,
) -> Result<(), CaptureSqlFailure> {
    if rows.len() != 1 {
        return Err(CaptureSqlFailure::UnknownLayout);
    }
    if rows[0].fields.len() != width {
        return Err(CaptureSqlFailure::RowInvalid);
    }
    for index in 0..width {
        if !normal_safety_bool(&rows[0], index)? {
            return Err(CaptureSqlFailure::UnknownLayout);
        }
    }
    Ok(())
}

fn normal_safety_bool(row: &CapturedDbRow, index: usize) -> Result<bool, CaptureSqlFailure> {
    match field(row, index)? {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => Err(CaptureSqlFailure::RowInvalid),
    }
}

// Normal-only file layout facts never enter common materials, hashes or equality.
fn verify_normal_file_settings(rows: &[CapturedDbRow]) -> Result<(), CaptureSqlFailure> {
    const MAIN_REQUIRED: u32 = (1 << 11) - 1;
    const TIMEZONE_PAIR: u32 = (1 << 11) | (1 << 12);
    const MAIN_ALLOWED: u32 = MAIN_REQUIRED | TIMEZONE_PAIR;
    const AUTO_REQUIRED: u32 = (1 << 0) | (1 << 8) | (((1 << 6) - 1) << 13);
    const MAIN_OVERRIDDEN: u32 = (1 << 0) | (1 << 8);
    let mut main = 0_u32;
    let mut auto = 0_u32;
    for row in rows {
        if row.projection != NORMAL_FILE_SETTINGS.name || row.fields.len() != 4 {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        let bit = match field(row, 0)? {
            "1" => 1_u32 << 0,
            "2" => 1_u32 << 1,
            "3" => 1_u32 << 2,
            "4" => 1_u32 << 3,
            "5" => 1_u32 << 4,
            "6" => 1_u32 << 5,
            "7" => 1_u32 << 6,
            "8" => 1_u32 << 7,
            "9" => 1_u32 << 8,
            "10" => 1_u32 << 9,
            "11" => 1_u32 << 10,
            "12" => 1_u32 << 11,
            "13" => 1_u32 << 12,
            "14" => 1_u32 << 13,
            "15" => 1_u32 << 14,
            "16" => 1_u32 << 15,
            "17" => 1_u32 << 16,
            "18" => 1_u32 << 17,
            "19" => 1_u32 << 18,
            "0" => return Err(CaptureSqlFailure::UnknownLayout),
            _ => return Err(CaptureSqlFailure::RowInvalid),
        };
        let applied = normal_safety_bool(row, 2)?;
        if !normal_safety_bool(row, 3)? {
            return Err(CaptureSqlFailure::UnknownLayout);
        }
        match field(row, 1)? {
            "1" => {
                if bit & MAIN_ALLOWED == 0
                    || main & bit != 0
                    || applied != (bit & MAIN_OVERRIDDEN == 0)
                {
                    return Err(CaptureSqlFailure::UnknownLayout);
                }
                main |= bit;
            }
            "2" => {
                if bit & AUTO_REQUIRED == 0 || auto & bit != 0 || !applied {
                    return Err(CaptureSqlFailure::UnknownLayout);
                }
                auto |= bit;
            }
            "0" => return Err(CaptureSqlFailure::UnknownLayout),
            _ => return Err(CaptureSqlFailure::RowInvalid),
        }
    }
    if (main != MAIN_REQUIRED && main != MAIN_ALLOWED) || auto != AUTO_REQUIRED {
        return Err(CaptureSqlFailure::UnknownLayout);
    }
    Ok(())
}

async fn collect_in_snapshot(
    client: &Client,
    expected: &CaptureDbExpectation,
    budget: &mut CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<CapturedDbFacts, CaptureSqlFailure> {
    let mut rows = Vec::new();
    let mut sensitive = Vec::new();
    let mut credential_ids = BTreeSet::new();
    let mut canary_count = 0_u64;
    for projection in ALL_PROJECTIONS {
        let read = read_projection(client, projection, expected, budget, clock).await?;
        if projection.sensitive {
            for row in read {
                validate_sensitive(&row)?;
                if row.projection == "canary" {
                    canary_count = canary_count
                        .checked_add(1)
                        .ok_or(CaptureSqlFailure::Bounds)?;
                    if field(&row, 0)? != expected.dataset_id
                        || field(&row, 1)? != expected.deployment_id
                        || field(&row, 2)? != expected.tenant_id
                    {
                        return Err(CaptureSqlFailure::SourceMismatch);
                    }
                } else if row.projection == "credential_keys"
                    && !credential_ids.insert(field(&row, 0)?.to_owned())
                {
                    return Err(CaptureSqlFailure::RowInvalid);
                }
                let bytes =
                    serde_json::to_vec(&row.fields).map_err(|_| CaptureSqlFailure::RowInvalid)?;
                sensitive.push(SensitiveCapturedRow {
                    projection: row.projection,
                    encoded: SecretBytes::new(bytes),
                });
            }
        } else {
            rows.extend(read);
        }
    }
    if canary_count != 1 {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    for reference in rows.iter().filter(|r| r.projection == "mcp_key_references") {
        if !credential_ids.contains(field(reference, 2)?) {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    verify_identity(&rows, expected)?;
    verify_frontier(&rows)?;
    budget.reserve_known(0, 0, EXPECTED_CATALOG_ENTRY_MEMORY, clock)?;
    verify_catalog(&rows, budget, clock)?;
    let migration_count =
        u64::try_from(native::NATIVE_MIGRATION_COUNT).map_err(|_| CaptureSqlFailure::Bounds)?;
    let migration_rows = rows.iter().filter(|r| r.projection == "migrations").count();
    if migration_rows != native::NATIVE_MIGRATION_COUNT {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    // Preflight has already bounded EVERY ledger field in this very transaction. This same
    // Client remains inside that snapshot while the original registered validator runs.
    let repeat_bytes = rows
        .iter()
        .filter(|r| r.projection == "migrations")
        .try_fold(0_u64, |n, row| {
            row.fields.iter().flatten().try_fold(n, |n, s| {
                n.checked_add(s.len() as u64)
                    .ok_or(CaptureSqlFailure::Bounds)
            })
        })?;
    budget.reserve_known(
        migration_count
            .checked_add(3)
            .ok_or(CaptureSqlFailure::Bounds)?,
        migration_count
            .checked_add(3)
            .ok_or(CaptureSqlFailure::Bounds)?,
        repeat_bytes,
        clock,
    )?;
    let duration = budget.remaining(clock)?;
    tokio::time::timeout(duration, native::validate_current(client))
        .await
        .map_err(|_| CaptureSqlFailure::Database)?
        .map_err(|_| CaptureSqlFailure::SourceMismatch)?;
    budget.remaining(clock)?;
    let identity = rows
        .iter()
        .find(|r| r.projection == "pg_identity")
        .ok_or(CaptureSqlFailure::SourceMismatch)?;
    let system_identifier = field(identity, 0)?.to_owned();
    let database_oid = field(identity, 1)?
        .parse()
        .map_err(|_| CaptureSqlFailure::RowInvalid)?;
    let schema_sha256 = hash_rows(&rows, |name| name.starts_with("catalog_"))?;
    let migrations_sha256 = hash_rows(&rows, |name| name == "migrations")?;
    let frontier_sha256 = hash_rows(&rows, |name| {
        matches!(
            name,
            "calls" | "attempts" | "runs" | "occupancy" | "run_events"
        )
    })?;
    Ok(CapturedDbFacts {
        rows,
        sensitive,
        schema_sha256,
        migrations_sha256,
        frontier_sha256,
        system_identifier,
        database_oid,
    })
}

fn field(row: &CapturedDbRow, index: usize) -> Result<&str, CaptureSqlFailure> {
    row.fields
        .get(index)
        .and_then(Option::as_deref)
        .ok_or(CaptureSqlFailure::RowInvalid)
}
fn hash_rows(
    rows: &[CapturedDbRow],
    include: impl Fn(&str) -> bool,
) -> Result<[u8; 32], CaptureSqlFailure> {
    let mut sha = Sha256::new();
    for row in rows.iter().filter(|row| include(row.projection)) {
        let bytes = serde_json::to_vec(&(row.projection, &row.fields))
            .map_err(|_| CaptureSqlFailure::RowInvalid)?;
        sha.update((bytes.len() as u64).to_be_bytes());
        sha.update(bytes);
    }
    Ok(sha.finalize().into())
}
fn parse_unsigned(text: &str) -> Result<u64, CaptureSqlFailure> {
    let value = text
        .parse::<u64>()
        .map_err(|_| CaptureSqlFailure::RowInvalid)?;
    if value.to_string() != text {
        return Err(CaptureSqlFailure::RowInvalid);
    }
    Ok(value)
}
fn hex(bytes: &[u8; 32]) -> String {
    let mut out = String::with_capacity(64);
    for byte in bytes {
        use std::fmt::Write;
        let _bounded = write!(out, "{byte:02x}");
    }
    out
}
fn verify_identity(
    rows: &[CapturedDbRow],
    expected: &CaptureDbExpectation,
) -> Result<(), CaptureSqlFailure> {
    let one = |name| {
        let mut found = rows.iter().filter(|r| r.projection == name);
        let row = found.next().ok_or(CaptureSqlFailure::SourceMismatch)?;
        if found.next().is_some() {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
        Ok(row)
    };
    let pg = one("pg_identity")?;
    if field(pg, 0)? != expected.system_identifier
        || field(pg, 1)?.parse::<u32>().ok() != Some(expected.database_oid)
        || field(pg, 2)?
            .parse::<u32>()
            .ok()
            .filter(|n| *n > 0)
            .is_none()
        || field(pg, 3)?
            .parse::<u64>()
            .ok()
            .filter(|n| *n > 0)
            .is_none()
    {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    let dataset = one("dataset")?;
    for (i, want) in [
        &expected.dataset_id,
        &expected.deployment_id,
        &expected.tenant_id,
    ]
    .into_iter()
    .enumerate()
    {
        if field(dataset, i)? != want {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    if field(dataset, 3)? != "1" {
        return Err(CaptureSqlFailure::SourceMismatch);
    }
    let store = one("store")?;
    for (i, want) in [
        &expected.store_id,
        &expected.root_device,
        &expected.root_inode,
        &expected.root_uid,
    ]
    .into_iter()
    .enumerate()
    {
        if field(store, i)? != want {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    Ok(())
}

fn validate_sensitive(row: &CapturedDbRow) -> Result<(), CaptureSqlFailure> {
    match row.projection {
        "canary" if field(row, 4)? == "1" && field(row, 5)? == "1" => Ok(()),
        "credential_keys" => {
            use openbot_domain::vault::envelope::EnvelopeV2;
            let raw = field(row, 2)?;
            #[derive(Deserialize)]
            #[serde(deny_unknown_fields)]
            struct FlatEnvelope {
                version: u32,
                key_version: u32,
                dek_nonce: String,
                wrapped_dek: String,
                nonce: String,
                ciphertext: String,
            }
            let mut flat: FlatEnvelope =
                serde_json::from_str(raw).map_err(|_| CaptureSqlFailure::UnknownLayout)?;
            let shape = flat.version == 2
                && flat.key_version == 1
                && !flat.dek_nonce.is_empty()
                && !flat.wrapped_dek.is_empty()
                && !flat.nonce.is_empty()
                && !flat.ciphertext.is_empty();
            flat.dek_nonce.zeroize();
            flat.wrapped_dek.zeroize();
            flat.nonce.zeroize();
            flat.ciphertext.zeroize();
            if !shape {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            let envelope = EnvelopeV2::parse(raw).map_err(|_| CaptureSqlFailure::UnknownLayout)?;
            if envelope.key_version().get() != 1 {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            Ok(())
        }
        _ => Err(CaptureSqlFailure::UnknownLayout),
    }
}

fn verify_frontier(rows: &[CapturedDbRow]) -> Result<(), CaptureSqlFailure> {
    let mut calls = BTreeMap::new();
    let mut runs = BTreeMap::new();
    let mut events = BTreeMap::new();
    for row in rows.iter().filter(|r| r.projection == "calls") {
        if calls.insert(field(row, 0)?, row).is_some() {
            return Err(CaptureSqlFailure::RowInvalid);
        }
    }
    for row in rows.iter().filter(|r| r.projection == "runs") {
        if !matches!(
            field(row, 2)?,
            "queued" | "running" | "completed" | "failed" | "cancelled" | "reconciliation_required"
        ) || runs.insert(field(row, 0)?, row).is_some()
        {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        if matches!(field(row, 2)?, "queued" | "running") {
            return Err(CaptureSqlFailure::CommitUnknown);
        }
    }
    // Calls and attempts are independent inventories. A legacy NOT VALID foreign key
    // cannot establish a call's run, even when that call has never had an attempt.
    for call in calls.values() {
        if !runs.contains_key(field(call, 1)?) {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    for row in rows.iter().filter(|r| r.projection == "run_events") {
        let run = runs
            .get(field(row, 0)?)
            .ok_or(CaptureSqlFailure::SourceMismatch)?;
        if field(row, 1)? != field(run, 1)?
            || events
                .insert((field(row, 0)?, field(row, 2)?), row)
                .is_some()
        {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    let mut attempts = BTreeSet::new();
    for row in rows.iter().filter(|r| r.projection == "attempts") {
        let call = calls
            .get(field(row, 0)?)
            .ok_or(CaptureSqlFailure::SourceMismatch)?;
        if !attempts.insert((field(row, 0)?, field(row, 1)?))
            || field(row, 8)? != field(call, 1)?
            || field(row, 9)? != field(call, 2)?
        {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
        if !matches!(
            field(row, 3)?,
            "decision_recorded" | "executing" | "completed" | "reconciliation_required" | "aborted"
        ) {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        if let Some(commit) = row.fields.get(4).and_then(Option::as_deref)
            && !matches!(commit, "committed" | "not_committed" | "unknown")
        {
            return Err(CaptureSqlFailure::RowInvalid);
        }
        if field(row, 3)? == "executing" {
            return Err(CaptureSqlFailure::CommitUnknown);
        }
        if !runs.contains_key(field(call, 1)?) {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    for row in rows.iter().filter(|r| r.projection == "occupancy") {
        let run = runs
            .get(field(row, 1)?)
            .ok_or(CaptureSqlFailure::SourceMismatch)?;
        if field(row, 0)? != field(run, 1)? || field(run, 2)? != "reconciliation_required" {
            return Err(CaptureSqlFailure::SourceMismatch);
        }
    }
    for run in runs.values() {
        if let Some(seq) = run.fields.get(4).and_then(Option::as_deref) {
            let event = events
                .get(&(field(run, 0)?, seq))
                .ok_or(CaptureSqlFailure::SourceMismatch)?;
            if field(event, 4)? != "true" {
                return Err(CaptureSqlFailure::SourceMismatch);
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod capture_frontier_regression_tests {
    use super::*;

    fn row(projection: &'static str, fields: &[Option<&str>]) -> CapturedDbRow {
        CapturedDbRow {
            projection,
            fields: fields
                .iter()
                .map(|value| value.map(str::to_owned))
                .collect(),
        }
    }

    fn writer_facts(rows: Vec<CapturedDbRow>) -> CapturedDbFacts {
        CapturedDbFacts {
            rows, sensitive: Vec::new(), schema_sha256: [0; 32],
            migrations_sha256: [0; 32], frontier_sha256: [0; 32],
            system_identifier: "owned-writer-test".to_owned(), database_oid: 1,
        }
    }

    #[test]
    fn projection_selection_refuses_before_any_output_and_preserves_known_rows() {
        let facts = writer_facts(vec![row("calls", &[Some("call"), Some("run"), Some("tool")])]);
        let refused: [&[&str]; 6] = [
            &[], &["unknown"], &["canary"], &["calls", "unknown"],
            &["calls", "canary"], &["calls", "calls"],
        ];
        for names in refused {
            let mut output = b"prior".to_vec();
            assert_eq!(facts.write_projection(names, &mut output),
                Err(CaptureSqlFailure::UnknownLayout));
            assert_eq!(output, b"prior");
        }
        let mut output = Vec::new();
        assert_eq!(facts.write_projection(&["calls"], &mut output), Ok(()));
        assert_eq!(output, b"[\"calls\",[\"call\",\"run\",\"tool\"]]\n");
        let mut no_rows = Vec::new();
        assert_eq!(facts.write_projection(&["profiles"], &mut no_rows), Ok(()));
        // An actual known zero-row selection creates no invented absence/header material.
        assert!(no_rows.is_empty());
    }

    #[test]
    fn orphan_call_without_attempt_is_rejected() {
        let rows = [row(
            "calls",
            &[Some("call"), Some("missing-run"), Some("tool")],
        )];
        assert_eq!(
            verify_frontier(&rows),
            Err(CaptureSqlFailure::SourceMismatch)
        );
    }

    #[test]
    fn call_without_attempt_with_existing_terminal_run_is_retained() {
        let rows = [
            row("calls", &[Some("call"), Some("run"), Some("tool")]),
            row(
                "runs",
                &[Some("run"), Some("thread"), Some("completed"), None, None],
            ),
        ];
        assert_eq!(verify_frontier(&rows), Ok(()));
    }
}

#[cfg(test)]
mod normal_config_file_settings_tests {
    use super::*;

    fn setting(code: &str, source: &str, applied: bool) -> CapturedDbRow {
        CapturedDbRow {
            projection: "normal_file_settings",
            fields: vec![
                Some(code.to_owned()),
                Some(source.to_owned()),
                Some(applied.to_string()),
                Some("true".to_owned()),
            ],
        }
    }

    fn complete(with_timezone: bool) -> Vec<CapturedDbRow> {
        let mut rows = (1..=11)
            .map(|code| setting(&code.to_string(), "1", code != 1 && code != 9))
            .collect::<Vec<_>>();
        if with_timezone {
            rows.push(setting("12", "1", true));
            rows.push(setting("13", "1", true));
        }
        for code in [1, 9, 14, 15, 16, 17, 18, 19] {
            rows.push(setting(&code.to_string(), "2", true));
        }
        rows
    }

    #[test]
    fn exact_main_and_auto_layouts_accept_only_whole_timezone_pair() {
        assert_eq!(verify_normal_file_settings(&complete(false)), Ok(()));
        assert_eq!(verify_normal_file_settings(&complete(true)), Ok(()));
        let mut partial = complete(false);
        partial.push(setting("12", "1", true));
        assert_eq!(
            verify_normal_file_settings(&partial),
            Err(CaptureSqlFailure::UnknownLayout)
        );
    }

    #[test]
    fn missing_duplicate_extra_and_wrong_source_are_rejected() {
        let mut missing = complete(false);
        missing.remove(1);
        assert_eq!(
            verify_normal_file_settings(&missing),
            Err(CaptureSqlFailure::UnknownLayout)
        );
        let mut duplicate = complete(false);
        duplicate.push(setting("1", "1", false));
        assert_eq!(
            verify_normal_file_settings(&duplicate),
            Err(CaptureSqlFailure::UnknownLayout)
        );
        let mut extra = complete(false);
        extra.push(setting("14", "1", true));
        assert_eq!(
            verify_normal_file_settings(&extra),
            Err(CaptureSqlFailure::UnknownLayout)
        );
        let mut wrong_source = complete(false);
        wrong_source[1].fields[1] = Some("2".to_owned());
        assert_eq!(
            verify_normal_file_settings(&wrong_source),
            Err(CaptureSqlFailure::UnknownLayout)
        );
    }

    #[test]
    fn override_error_and_malformed_fields_are_rejected() {
        for index in [0, 8] {
            let mut main_applied = complete(false);
            main_applied[index].fields[2] = Some("true".to_owned());
            assert_eq!(
                verify_normal_file_settings(&main_applied),
                Err(CaptureSqlFailure::UnknownLayout)
            );
        }
        let mut auto_not_applied = complete(false);
        auto_not_applied[11].fields[2] = Some("false".to_owned());
        assert_eq!(
            verify_normal_file_settings(&auto_not_applied),
            Err(CaptureSqlFailure::UnknownLayout)
        );
        let mut error = complete(false);
        error[0].fields[3] = Some("false".to_owned());
        assert_eq!(
            verify_normal_file_settings(&error),
            Err(CaptureSqlFailure::UnknownLayout)
        );
        let mut null = complete(false);
        null[0].fields[3] = None;
        assert_eq!(
            verify_normal_file_settings(&null),
            Err(CaptureSqlFailure::RowInvalid)
        );
        let mut malformed = complete(false);
        malformed[0].fields[0] = Some("+1".to_owned());
        assert_eq!(
            verify_normal_file_settings(&malformed),
            Err(CaptureSqlFailure::RowInvalid)
        );
    }
}

