#[derive(Deserialize)]
struct CatalogExpectation {
    projection: String,
    key: Vec<String>,
    fields: Vec<(usize, Option<String>)>,
}

fn verify_catalog(
    rows: &[CapturedDbRow],
    budget: &CaptureSqlBudget,
    clock: &dyn CaptureClockCheck,
) -> Result<(), CaptureSqlFailure> {
    // Validate one frozen expectation at a time. No unbounded Value/Vec oracle tree is built.
    let mut matched = vec![false; rows.len()];
    for (index, row) in rows
        .iter()
        .enumerate()
        .filter(|(_, r)| r.projection.starts_with("catalog_"))
    {
        if row.projection == "catalog_namespaces" {
            let name = field(row, 0)?;
            if !matches!(
                name,
                "public" | "openbot_internal" | "pg_catalog" | "information_schema" | "pg_toast"
            ) {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            matched[index] = true;
        } else if row.projection == "catalog_extensions" {
            if field(row, 0)? != "plpgsql"
                || field(row, 1)? != "1.0"
                || field(row, 2)? != "pg_catalog"
            {
                return Err(CaptureSqlFailure::UnknownLayout);
            }
            matched[index] = true;
        }
    }
    struct Oracle<'a> {
        rows: &'a [CapturedDbRow],
        matched: &'a mut [bool],
        budget: &'a CaptureSqlBudget,
        clock: &'a dyn CaptureClockCheck,
    }
    impl<'de> serde::de::Visitor<'de> for Oracle<'_> {
        type Value = ();
        fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.write_str("the compiled finite catalog expectation array")
        }
        fn visit_seq<A: serde::de::SeqAccess<'de>>(self, mut seq: A) -> Result<(), A::Error> {
            while let Some(entry) = seq.next_element::<CatalogExpectation>()? {
                self.budget
                    .remaining(self.clock)
                    .map_err(|_| serde::de::Error::custom("capture clock"))?;
                let found = self.rows.iter().enumerate().find(|(index, row)| {
                    !self.matched[*index]
                        && row.projection == entry.projection
                        && entry.key.iter().enumerate().all(|(i, key)| {
                            row.fields.get(i).and_then(Option::as_deref) == Some(key.as_str())
                        })
                });
                let (index, row) =
                    found.ok_or_else(|| serde::de::Error::custom("catalog identity"))?;
                if entry
                    .fields
                    .iter()
                    .any(|(index, expected)| row.fields.get(*index) != Some(expected))
                {
                    return Err(serde::de::Error::custom("catalog shape"));
                }
                self.matched[index] = true;
            }
            Ok(())
        }
    }
    let mut decoder = serde_json::Deserializer::from_str(EXPECTED_CATALOG);
    serde::de::Deserializer::deserialize_seq(
        &mut decoder,
        Oracle {
            rows,
            matched: &mut matched,
            budget,
            clock,
        },
    )
    .map_err(|_| CaptureSqlFailure::UnknownLayout)?;
    decoder
        .end()
        .map_err(|_| CaptureSqlFailure::UnknownLayout)?;
    if rows
        .iter()
        .enumerate()
        .any(|(index, row)| row.projection.starts_with("catalog_") && !matched[index])
    {
        return Err(CaptureSqlFailure::UnknownLayout);
    }
    Ok(())
}

